        {
          "title": "\u5BE6\u52D9\u8A9E\u6CD5\u89E3\u6790 (4)",
          "content": "\u4EE5\u4E0B\u7A0B\u5F0F\u7BC4\u4F8B\u5C55\u793A\u4E86\u7522\u696D\u6A19\u6E96\u7684\u67B6\u69CB\u8207\u7528\u6CD5\u3002\u8ACB\u7279\u5225\u6CE8\u610F\u8CC7\u6599\u578B\u5225\u5BA3\u544A\u3001\u4F5C\u7528\u57DF\uFF0C\u4EE5\u53CA\u6642\u5E8F\u63A7\u5236\u7684\u7D30\u7BC0\u3002\u6B64\u7D50\u69CB\u5EE3\u6CDB\u61C9\u7528\u65BC\u4E3B\u6D41 IC \u8A2D\u8A08\u5927\u5EE0\u7684\u9A57\u8B49\u74B0\u5883\u4E2D\u3002",
          "code": "module alu_4_bit (\n  input  logic  [3:0] a,\n  input  logic  [3:0] b,\n  input  logic  [1:0] op_code,\n  output logic  [3:0] result\n);\n\n  // This is a combinational always block\n  always_comb begin\n    case (op_code)\n      2'b00: begin\n        result = a + b;  // Addition\n      end\n      2'b01: begin\n        result = a - b;  // Subtraction\n      end\n      2'b10: begin\n        result = a & b;  // Bitwise AND\n      end\n      2'b11: begin\n        result = a | b;  // Bitwise OR\n      end\n    endcase\n  end\n\nendmodule",
          "lang": "verilog"
        },
        {
          "title": "\u5BE6\u52D9\u8A9E\u6CD5\u89E3\u6790 (5)",
          "content": "\u4EE5\u4E0B\u7A0B\u5F0F\u7BC4\u4F8B\u5C55\u793A\u4E86\u7522\u696D\u6A19\u6E96\u7684\u67B6\u69CB\u8207\u7528\u6CD5\u3002\u8ACB\u7279\u5225\u6CE8\u610F\u8CC7\u6599\u578B\u5225\u5BA3\u544A\u3001\u4F5C\u7528\u57DF\uFF0C\u4EE5\u53CA\u6642\u5E8F\u63A7\u5236\u7684\u7D30\u7BC0\u3002\u6B64\u7D50\u69CB\u5EE3\u6CDB\u61C9\u7528\u65BC\u4E3B\u6D41 IC \u8A2D\u8A08\u5927\u5EE0\u7684\u9A57\u8B49\u74B0\u5883\u4E2D\u3002",
          "code": "function logic func_and;\n  input logic a, b;\n  begin\n    func_and = a & b;  // depends on both a and b\n  end\nendfunction\n\nlogic x, y, z;\n\nalways @* begin  // @* may miss x and y\n  z = func_and(x, y);  \nend",
          "lang": "verilog"
        },
        {
          "title": "\u5BE6\u52D9\u8A9E\u6CD5\u89E3\u6790 (6)",
          "content": "\u4EE5\u4E0B\u7A0B\u5F0F\u7BC4\u4F8B\u5C55\u793A\u4E86\u7522\u696D\u6A19\u6E96\u7684\u67B6\u69CB\u8207\u7528\u6CD5\u3002\u8ACB\u7279\u5225\u6CE8\u610F\u8CC7\u6599\u578B\u5225\u5BA3\u544A\u3001\u4F5C\u7528\u57DF\uFF0C\u4EE5\u53CA\u6642\u5E8F\u63A7\u5236\u7684\u7D30\u7BC0\u3002\u6B64\u7D50\u69CB\u5EE3\u6CDB\u61C9\u7528\u65BC\u4E3B\u6D41 IC \u8A2D\u8A08\u5927\u5EE0\u7684\u9A57\u8B49\u74B0\u5883\u4E2D\u3002",
          "code": "always_comb begin      // infers x and y\n  z = func_and(x, y);\nend",
          "lang": "verilog"
        },
        {
          "title": "\u5BE6\u52D9\u8A9E\u6CD5\u89E3\u6790 (7)",
          "content": "\u4EE5\u4E0B\u7A0B\u5F0F\u7BC4\u4F8B\u5C55\u793A\u4E86\u7522\u696D\u6A19\u6E96\u7684\u67B6\u69CB\u8207\u7528\u6CD5\u3002\u8ACB\u7279\u5225\u6CE8\u610F\u8CC7\u6599\u578B\u5225\u5BA3\u544A\u3001\u4F5C\u7528\u57DF\uFF0C\u4EE5\u53CA\u6642\u5E8F\u63A7\u5236\u7684\u7D30\u7BC0\u3002\u6B64\u7D50\u69CB\u5EE3\u6CDB\u61C9\u7528\u65BC\u4E3B\u6D41 IC \u8A2D\u8A08\u5927\u5EE0\u7684\u9A57\u8B49\u74B0\u5883\u4E2D\u3002",
          "code": "module data_selector_with_latch (\n    input  wire a_in,\n    input  wire b_in,\n    input  wire sel,\n    input  wire enable,\n    output reg  data_out\n);\n\n    // This is the combinational part of the logic, a 2-to-1 mux\n    wire mux_out;\n    assign mux_out = sel ? a_in : b_in;\n\n    // This is the sequential part (the latch) that will hold the value\n    always_latch begin\n        if (enable) begin\n            data_out = mux_out;\n        end      \n    end\n\nendmodule",
          "lang": "verilog"
        },
        {
          "title": "\u5BE6\u52D9\u8A9E\u6CD5\u89E3\u6790 (8)",
          "content": "\u4EE5\u4E0B\u7A0B\u5F0F\u7BC4\u4F8B\u5C55\u793A\u4E86\u7522\u696D\u6A19\u6E96\u7684\u67B6\u69CB\u8207\u7528\u6CD5\u3002\u8ACB\u7279\u5225\u6CE8\u610F\u8CC7\u6599\u578B\u5225\u5BA3\u544A\u3001\u4F5C\u7528\u57DF\uFF0C\u4EE5\u53CA\u6642\u5E8F\u63A7\u5236\u7684\u7D30\u7BC0\u3002\u6B64\u7D50\u69CB\u5EE3\u6CDB\u61C9\u7528\u65BC\u4E3B\u6D41 IC \u8A2D\u8A08\u5927\u5EE0\u7684\u9A57\u8B49\u74B0\u5883\u4E2D\u3002",
          "code": "module sync_counter_3bit (\n    input  wire clk,\n    input  wire reset_n, // Active-low reset\n    output reg  [2:0] count\n);\n\n    // This is the sequential always block, triggered on a clock edge\n    always_ff @(posedge clk or negedge reset_n) begin\n        if (!reset_n) begin\n            // Asynchronous reset: sets the count to 0 when reset_n is low\n            count <= 3'b000;\n        end else begin\n            // On the positive edge of the clock, increment the count\n            count <= count + 1'b1;\n        end\n    end\n\nendmodule",
          "lang": "verilog"
        },
        {
          "title": "\u5BE6\u4F5C\u6F14\u7DF4 (Hands-on Lab)",
          "content": "\u70BA\u4E86\u978F\u56FA\u6B64\u6982\u5FF5\uFF0C\u8ACB\u5728 EDA Playground (VCS \u6216 Xcelium \u74B0\u5883) \u5BE6\u4F5C\u4EE5\u4E0B Lab\uFF1A\n\n1. **\u57FA\u790E\u5EFA\u7ACB**\uFF1A\u5728\u60A8\u7684 `testbench.sv` \u4E2D\u52A0\u5165\u4E0B\u65B9\u7A0B\u5F0F\u78BC\u6A21\u677F\u3002\n2. **\u529F\u80FD\u6A21\u64EC**\uFF1A\u4F7F\u7528 `$display` \u6216 `$monitor` \u8F38\u51FA\u6A21\u64EC\u6CE2\u5F62\u3002\n3. **\u908A\u754C\u6E2C\u8A66 (Corner Cases)**\uFF1A\u5617\u8A66\u6CE8\u5165\u9810\u671F\u5916\u7684\u6578\u503C (\u5982 `x` \u6216 `z`)\uFF0C\u89C0\u5BDF\u8A2D\u8A08\u7684\u5F37\u5065\u6027\u8207\u7DE8\u8B6F\u5668\u884C\u70BA\u3002",
          "code": '`timescale 1ns/1ps\n\n/**\n * @title Hands-on Lab: SystemVerilog always_comb, always_ff\n * @brief Professional Verification Testbench Template\n */\nmodule tb_lab_75();\n\n  // --- Clock and Reset Generation ---\n  logic clk;\n  logic rst_n;\n\n  initial begin\n    clk = 0;\n    forever #5 clk = ~clk; // 100MHz Clock\n  end\n\n  initial begin\n    rst_n = 0;\n    #20 rst_n = 1;\n  end\n\n  // --- Interface & DUT Instances (Placeholder) ---\n  // dut_if vif(.clk(clk), .rst_n(rst_n));\n  // dut_top u_dut(.clk(clk), .rst_n(rst_n), /* ports */);\n\n  // --- Main Verification Thread ---\n  initial begin\n    $timeformat(-9, 2, " ns", 10);\n    $display("==================================================");\n    $display("   [UVM/SV LAB START] Commencing simulation       ");\n    $display("   Topic: %s", "SystemVerilog always_comb, always_ff");\n    $display("==================================================");\n    \n    // Wait for reset release\n    @(posedge rst_n);\n    @(posedge clk);\n\n    // TODO: Insert your specific verification logic for SystemVerilog always_comb, always_ff here.\n    // Ensure all critical assertions are covered.\n    \n    #1000;\n    $display("[%0t] Simulation seamlessly concluded.", $time);\n    $finish;\n  end\n  \n  // --- Standard Dumping Logic ---\n  initial begin\n    $dumpfile("dump.vcd");\n    $dumpvars(0, tb_lab_75);\n  end\n\nendmodule',
          "lang": "verilog"
        }
