          "code": '`timescale 1ns/1ps\n\n/**\n * @title Hands-on Lab: Sequence action macros for pre-existing items\n * @brief Professional Verification Testbench Template\n */\n`include "uvm_macros.svh"\nimport uvm_pkg::*;\n\nmodule tb_lab_100();\n\n  // --- Clock and Reset Generation ---\n  logic clk;\n  logic rst_n;\n\n  initial begin\n    clk = 0;\n    forever #5 clk = ~clk; // 100MHz Clock\n  end\n\n  initial begin\n    rst_n = 0;\n    #20 rst_n = 1;\n  end\n\n  // --- Main Verification Thread ---\n  initial begin\n    $timeformat(-9, 2, " ns", 10);\n    $display("==================================================");\n    $display("   [UVM LAB START] Commencing simulation       ");\n    $display("   Topic: %s", "Sequence action macros for pre-existing items");\n    $display("==================================================");\n    \n    // Wait for reset release\n    @(posedge rst_n);\n    @(posedge clk);\n\n    // TODO: Insert your specific UVM components testing for Sequence action macros for pre-existing items here.\n    \n    #1000;\n    $display("[%0t] Simulation seamlessly concluded.", $time);\n    $finish;\n  end\n  \n  // --- Standard Dumping Logic ---\n  initial begin\n    $dumpfile("dump.vcd");\n    $dumpvars(0, tb_lab_100);\n  end\n\nendmodule',
          "lang": "verilog"
