        {
          "title": "\u5BE6\u52D9\u8A9E\u6CD5\u89E3\u6790 (12)",
          "content": "\u4EE5\u4E0B\u7A0B\u5F0F\u7BC4\u4F8B\u5C55\u793A\u4E86\u7522\u696D\u6A19\u6E96\u7684\u67B6\u69CB\u8207\u7528\u6CD5\uFF0C\u5EFA\u8B70\u8B80\u8005\u5BE6\u6A5F\u6F14\u7DF4\u89C0\u5BDF\u5E95\u5C64 Callback \u884C\u70BA\u3002",
          "code": 'class reg_block extends uvm_reg_block;\n	rand 	reg_ctl 	m_reg_ctl;\n	rand 	reg_stat 	m_reg_stat;\n	rand 	reg_inten 	m_reg_inten;\n	\n	function new (string name = "reg_block");\n		super.new (name, UVM_NO_COVERAGE);\n	endfunction\n	\n	virtual function void build ();\n	\n		// Create an instance for every register\n		this.default_map = create_map ("", 0, 4, UVM_LITTLE_ENDIAN, 0);\n		this.m_reg_ctl = reg_ctl::type_id::create ("m_reg_ctl", , get_full_name);\n		this.m_reg_stat = reg_stat::type_id::create ("m_reg_stat", , get_full_name);\n		this.m_reg_inten = reg_inten::type_id::create ("m_reg_inten", , get_full_name);\n		\n		// Configure every register instance\n		this.m_reg_ctl.configure (this, null, "");\n		this.m_reg_stat.configure (this, null, "");\n		this.m_reg_inten.configure (this, null, "");\n		\n		// Call the build() function to build all register fields within each register\n		this.m_reg_ctl.build();\n		this.m_reg_stat.build();\n		this.m_reg_inten.build();\n		\n		// Add these registers to the default map\n		this.default_map.add_reg (this.m_reg_ctl, `UVM_REG_ADDR_WIDTH\'h0, "RW", 0);\n		this.default_map.add_reg (this.m_reg_stat, `UVM_REG_ADDR_WIDTH\'h4, "RO", 0);\n		this.default_map.add_reg (this.m_reg_inten, `UVM_REG_ADDR_WIDTH\'h8, "RW", 0);\n	endfunction\nendclass',
          "lang": "verilog"
        },
        {
          "title": "\u5BE6\u4F5C\u6F14\u7DF4 (Hands-on Lab)",
          "content": "\u70BA\u4E86\u978F\u56FA\u89C0\u5FF5\uFF0C\u8ACB\u5728 EDA Playground \u5BE6\u4F5C\u4E0B\u65B9 UVM \u6F14\u7DF4\u6A21\u677F\u3002\u89C0\u5BDF\u60A8\u7684\u7A0B\u5F0F\u82E5\u89F8\u767C UVM_ERROR \u5C07\u5982\u4F55\u56DE\u5831\u3002",
          "code": '`timescale 1ns/1ps\n\n/**\n * @title Hands-on Lab: UVM Register Model Classes\n * @brief Professional Verification Testbench Template\n */\n`include "uvm_macros.svh"\nimport uvm_pkg::*;\n\nmodule tb_lab_109();\n\n  // --- Clock and Reset Generation ---\n  logic clk;\n  logic rst_n;\n\n  initial begin\n    clk = 0;\n    forever #5 clk = ~clk; // 100MHz Clock\n  end\n\n  initial begin\n    rst_n = 0;\n    #20 rst_n = 1;\n  end\n\n  // --- Main Verification Thread ---\n  initial begin\n    $timeformat(-9, 2, " ns", 10);\n    $display("==================================================");\n    $display("   [UVM LAB START] Commencing simulation       ");\n    $display("   Topic: %s", "UVM Register Model Classes");\n    $display("==================================================");\n    \n    // Wait for reset release\n    @(posedge rst_n);\n    @(posedge clk);\n\n    // TODO: Insert your specific UVM components testing for UVM Register Model Classes here.\n    \n    #1000;\n    $display("[%0t] Simulation seamlessly concluded.", $time);\n    $finish;\n  end\n  \n  // --- Standard Dumping Logic ---\n  initial begin\n    $dumpfile("dump.vcd");\n    $dumpvars(0, tb_lab_109);\n  end\n\nendmodule',
          "lang": "verilog"
        }
